function ageFactor(a){return 1+Math.max(0,a-65)*0.03}
/**
 * Compare Medigap plans by zip code, age, and household eligibility.
 * @param {object}  p
 * @param {string}  p.zip               5-digit US zip code
 * @param {number}  p.age               Beneficiary age (65–99)
 * @param {boolean} [p.householdEligible] true only when two people from the same
 *                                       household are both enrolling. Each insurer
 *                                       defines "household" differently — show
 *                                       householdEligibility on each result to the user.
 * @param {string}  [p.planLetter]      Filter to a single plan letter, e.g. "G"
 * @param {string}  [p.sortBy]          "premium-asc" (default) | "premium-desc" | "insurer"
 * @returns {Array}
 */
function comparePlans(p){
  if(!p||!p.zip||p.age==null)throw new Error('zip and age are required');
  var zip=String(p.zip),age=Number(p.age),hh=!!p.householdEligible,letter=p.planLetter||null,sort=p.sortBy||'premium-asc';
  var zr=ZIP_CODES.find(function(z){return z.zip===zip});
  var factor=ageFactor(age)*(zr?zr.costMultiplier:1.0);
  var im={};INSURERS.forEach(function(i){im[i.id]=i});
  var results=PLANS.filter(function(pl){return!letter||pl.planLetter===letter}).map(function(pl){
    var ins=im[pl.insurerId];
    var rate=pl.householdDiscountRate||0;
    var discApplied=hh&&rate>0;
    var mp=Math.round(pl.basePremium*factor*(1-(discApplied?rate:0))*100)/100;
    return{id:pl.id,insurerName:ins.name,planLetter:pl.planLetter,monthlyPremium:mp,
      annualDeductible:pl.annualDeductible,outOfPocketLimit:pl.outOfPocketLimit,
      amBestRating:ins.amBestRating,moodyRating:ins.moodyRating,yearsInBusiness:ins.yearsInBusiness,
      householdDiscountRate:pl.householdDiscountRate,
      householdEligibility:pl.householdEligibility,
      householdDiscountNotes:pl.householdDiscountNotes,
      householdDiscountApplied:discApplied,
      notes:pl.notes,planType:pl.planType,
      partBDeductibleCovered:pl.partBDeductibleCovered,foreignTravelCovered:pl.foreignTravelCovered};
  });
  if(sort==='premium-desc')results.sort(function(a,b){return b.monthlyPremium-a.monthlyPremium});
  else if(sort==='insurer')results.sort(function(a,b){return a.insurerName.localeCompare(b.insurerName)});
  else results.sort(function(a,b){return a.monthlyPremium-b.monthlyPremium});
  return results;
}
/**
 * Aggregate pricing summary. Same params as comparePlans.
 * @param {object} p
 * @returns {object}
 */
function getPlansSummary(p){
  if(!p||!p.zip||p.age==null)throw new Error('zip and age are required');
  var zr=ZIP_CODES.find(function(z){return z.zip===String(p.zip)}),all=comparePlans(p);
  if(!all.length)return{state:zr?zr.state:'Unknown',county:zr?zr.county:'Unknown',totalPlans:0,lowestPremium:0,highestPremium:0,medianPremium:0,popularPlanLetter:'G',byLetter:[]};
  var sorted=all.map(function(x){return x.monthlyPremium}).sort(function(a,b){return a-b});
  var mid=Math.floor(sorted.length/2),med=sorted.length%2===0?(sorted[mid-1]+sorted[mid])/2:sorted[mid];
  var lm={};all.forEach(function(x){if(!lm[x.planLetter])lm[x.planLetter]=[];lm[x.planLetter].push(x.monthlyPremium)});
  var byLetter=Object.keys(lm).sort().map(function(lt){
    var v=lm[lt],s=[].concat(v).sort(function(a,b){return a-b});
    return{letter:lt,count:v.length,minPremium:Math.round(s[0]*100)/100,maxPremium:Math.round(s[s.length-1]*100)/100,avgPremium:Math.round(v.reduce(function(a,b){return a+b},0)/v.length*100)/100};
  });
  var pop=Object.keys(lm).sort(function(a,b){return lm[b].length-lm[a].length})[0];
  return{state:zr?zr.state:'Unknown',county:zr?zr.county:'Unknown',totalPlans:all.length,
    lowestPremium:Math.round(sorted[0]*100)/100,highestPremium:Math.round(sorted[sorted.length-1]*100)/100,
    medianPremium:Math.round(med*100)/100,popularPlanLetter:pop,byLetter:byLetter};
}
function getZipInfo(zip){return ZIP_CODES.find(function(z){return z.zip===String(zip)})||null}
function getPlanLetters(){return PLAN_LETTERS}

export{comparePlans,getPlansSummary,getZipInfo,getPlanLetters};
export{INSURERS as insurers,PLANS as plans,ZIP_CODES as zipCodes,PLAN_LETTERS as planLetters};
